function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // dog
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // tail
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70);
  ctx.lineTo(W/2 + 30 + 10 * Math.sin(t), H/2 + 90);
  ctx.stroke();

  // owner's hand
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2);
  ctx.lineTo(W/2 + 50, H/2 - 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 30);
  ctx.lineTo(W/2 + 70, H/2 - 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 30);
  ctx.lineTo(W/2 + 30, H/2 - 30);
  ctx.stroke();

  // distance between dog and owner's hand
  let distance = 100 + 20 * Math.sin(t);
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 30);
  ctx.lineTo(W/2 + 50, H/2 - distance);
  ctx.strokeStyle = 'gray';
  ctx.stroke();
  ctx.strokeStyle = 'black';

  ctx.restore();
}
